tasks.solution:
CREATE TABLE orders_load AS SELECT * FROM orders WHERE order_date >= '2026-06-01';
-- сбой: заказы за 15 июня пришли дважды
INSERT INTO orders_load SELECT * FROM orders WHERE order_date = '2026-06-15';
-- у части заказов потерялся клиент
UPDATE orders_load SET customer_id = NULL WHERE order_id % 97 = 0;
-- у части дата доставки «уехала» раньше даты заказа
UPDATE orders_load SET delivery_date = order_date - 2 WHERE order_id % 41 = 0 AND delivery_date IS NOT NULL;

SELECT COUNT(*) AS rows_total,
       COUNT(*) - COUNT(DISTINCT order_id) AS duplicate_ids,
       COUNT(*) FILTER (WHERE customer_id IS NULL) AS no_customer,
       COUNT(*) FILTER (WHERE delivery_date < order_date) AS delivery_before_order
FROM orders_load;

