WITH d AS (SELECT order_id FROM orders_load GROUP BY 1 HAVING COUNT(*) > 1) SELECT COUNT(*) AS rows_total, (SELECT COUNT(*) FROM orders_load WHERE order_id IN (SELECT order_id FROM d)) / 2 AS duplicate_ids, SUM(CASE WHEN customer_id IS NULL THEN 1 ELSE 0 END) AS no_customer, SUM(CASE WHEN delivery_date < order_date THEN 1 ELSE 0 END) AS delivery_before_order FROM orders_load

